package com.phoenix.business.web; import com.phoenix.business.domain.*;import com.phoenix.business.repository.*;import com.phoenix.business.service.AuditService;import com.phoenix.business.web.dto.AttendanceResponse;import com.phoenix.business.web.dto.PaymentResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/members") @RequiredArgsConstructor public class MemberController {private final MemberRepository repo;private final MembershipPlanRepository plans;private final PaymentRepository payments;private final AttendanceRepository attendance;private final AuditService audit;private final com.phoenix.business.service.MemberRemovalService removal;private final com.phoenix.business.service.MembershipExpiryService expiry;private final com.phoenix.business.service.BusinessTimeService businessTime;record Input(@NotBlank @Size(max=30)String memberCode,@NotBlank @Size(max=160)String name,@Size(max=30)String phone,@Email @Size(max=160)String email,String gender,LocalDate dateOfBirth,String address,String emergencyContact,@NotNull LocalDate joinDate,Long planId,LocalDate membershipStartDate,LocalDate expiryDate,Member.Status status,String notes,@Size(max=2800000)String photoData){}@GetMapping public Page<Member> list(@RequestParam(required=false)String q,@RequestParam(required=false)Member.Status status,@RequestParam(defaultValue="false")boolean archived,@PageableDefault(size=20,sort="name")Pageable p){if(!archived)expiry.expire();return repo.search(blank(q),status,archived,p);}@GetMapping("/{id}")public Member get(@PathVariable Long id){return repo.findById(id).orElseThrow();}@GetMapping("/{id}/profile")public Map<String,Object> profile(@PathVariable Long id){Member m=get(id);return Map.of("member",m,"payments",payments.findByMemberIdOrderByPaymentDateDesc(id).stream().map(PaymentResponse::from).toList(),"recentAttendance",attendance.findTop10ByMemberIdOrderByCheckedInAtDesc(id).stream().map(AttendanceResponse::from).toList());}@PostMapping public Member create(@Valid @RequestBody Input q){Member m=new Member();copy(m,q);m=repo.save(m);audit.record("MEMBER_CREATED","MEMBER",m.getId(),m.getMemberCode()+" "+m.getName());return m;}@PutMapping("/{id}")@org.springframework.transaction.annotation.Transactional public Member update(@PathVariable Long id,@Valid @RequestBody Input q){Member m=repo.findLockedById(id).orElseThrow();if(m.isArchived())throw new IllegalArgumentException("Restore this member before editing");copy(m,q);m=repo.save(m);audit.record("MEMBER_UPDATED","MEMBER",id,m.getMemberCode()+" "+m.getName());return m;}@DeleteMapping("/{id}")@PreAuthorize("hasAnyRole('OWNER','ADMIN')")public Map<String,String> delete(@PathVariable Long id){return Map.of("outcome",removal.remove(id));}@PostMapping("/{id}/restore")@PreAuthorize("hasAnyRole('OWNER','ADMIN')")public Member restore(@PathVariable Long id){return removal.restore(id);}private void copy(Member m,Input q){Long id=m.getId()==null?0:m.getId();if(q.email()!=null&&repo.existsByEmailIgnoreCaseAndIdNot(q.email(),id))throw new IllegalArgumentException("Email already belongs to another member");if(q.phone()!=null&&repo.existsByPhoneAndIdNot(q.phone(),id))throw new IllegalArgumentException("Phone already belongs to another member");m.setMemberCode(q.memberCode().trim());m.setName(q.name().trim());m.setPhone(blank(q.phone()));m.setEmail(blank(q.email()));m.setGender(blank(q.gender()));m.setDateOfBirth(q.dateOfBirth());m.setAddress(blank(q.address()));m.setEmergencyContact(blank(q.emergencyContact()));m.setJoinDate(q.joinDate());m.setPlan(q.planId()==null?null:plans.findById(q.planId()).orElseThrow());m.setMembershipStartDate(q.membershipStartDate());m.setExpiryDate(q.expiryDate());m.setStatus(q.status()==null?Member.Status.ACTIVE:q.status());if(m.getStatus()==Member.Status.ACTIVE&&m.getExpiryDate()!=null&&m.getExpiryDate().isBefore(businessTime.today()))m.setStatus(Member.Status.EXPIRED);m.setNotes(blank(q.notes()));if(q.photoData()!=null)m.setPhotoData(com.phoenix.business.service.MemberPhoto.validate(q.photoData()));}private String blank(String s){return s==null||s.isBlank()?null:s.trim();}}
